'use strict';
/**
 * The demo agency's client videos: short tall clips made on this computer with ffmpeg-static from three drawn scenes
 * (hook, the item, an end card), joined with cross-fades. Nothing is generated by a model and nothing is charged. Each clip has a
 * StudioVideo row in the stored shape (a finished one-clip video) and one matching 161-Quark spend in the agency wallet.
 */
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const { seeded } = require('../demo-brand/images');
const demoVideos = require('../demo-brand/videos');
const { QUARK_COSTS } = require('../../config/apiCosts');
const { TEMPLATES } = require('./constants');
const posters = require('./posters');
const { joinedAt, periodOf } = require('./build');

const DAY = 24 * 60 * 60 * 1000;

/** Which videos each client has made, oldest first: one or two a month since it joined, one in the current month. */
function videoPlan({ t, client: c, index }) {
  const out = []; const r = seeded(`vid:${c.slug}`);
  t.charges.forEach((at, i) => {
    const end = i + 1 < t.charges.length ? t.charges[i + 1] : t.now;
    const from = new Date(Math.max(at.getTime(), joinedAt(t, c).getTime() + 3 * DAY));
    if (from >= end) return;
    const n = i === t.charges.length - 1 ? 1 : 1 + ((index + i) % 2);
    for (let k = 0; k < n; k += 1) {
      const when = new Date(from.getTime() + (end.getTime() - from.getTime()) * ((k + 0.4 + r() * 0.3) / (n + 0.2)));
      if (when < t.now) out.push({ at: when, key: `v${out.length + 1}` });
    }
  });
  return out.map((v, n) => {
    const a = c.items[(n * 2 + index) % c.items.length]; const b = c.items[(n * 2 + index + 1) % c.items.length];
    const hook = TEMPLATES[(n * 3 + index) % TEMPLATES.length](c, a, b); const mid = TEMPLATES[(n * 3 + index + 6) % TEMPLATES.length](c, b, a);
    const end = { head: c.name, sub: c.offer.charAt(0).toUpperCase() + c.offer.slice(1) };
    return { ...v, client: c.slug, title: `${a.n}: a 10 second reel`, idea: `A short vertical video about ${a.n.toLowerCase()} for ${c.name}.`, scenes: [hook, mid, end], layout: (n + index) % 4 };
  });
}

const mp4Rel = (v) => `videos/${v.key}.mp4`;
const posterRel = (v) => `videos/${v.key}.jpg`;

/** Draws the three scenes, then the clip, under `dir` (skips what is there). Returns the reason when ffmpeg is missing or fails. */
function makeVideo({ dir, client: c, video: v, run = spawnSync, ffmpeg = demoVideos.ffmpegPath() }) {
  const clip = path.join(dir, mp4Rel(v)); const poster = path.join(dir, posterRel(v));
  fs.mkdirSync(path.dirname(clip), { recursive: true });
  const bufs = v.scenes.map((w, k) => posters.postJpg(c, w, { layout: (v.layout + k) % 4, w: 720, h: 1280, seedKey: `${v.key}${k}` }));
  fs.writeFileSync(poster, bufs[0]);
  if (fs.existsSync(clip)) return '';
  if (!ffmpeg) return 'ffmpeg is not available';
  const work = fs.mkdtempSync(path.join(path.dirname(clip), '.work-'));
  try {
    const files = bufs.map((b, k) => { const f = path.join(work, `s${k}.jpg`); fs.writeFileSync(f, b); return f; });
    const tmp = path.join(work, 'out.mp4');
    const res = run(ffmpeg, demoVideos.ffmpegArgs({ scenes: files, out: tmp, wide: false }), { timeout: 180000, encoding: 'utf8' });
    if (res.status !== 0 || !fs.existsSync(tmp)) return `ffmpeg failed (${String(res.stderr || res.error || '').slice(0, 160)})`;
    fs.renameSync(tmp, clip);
    return '';
  } finally { fs.rmSync(work, { recursive: true, force: true }); }
}

/** The StudioVideo row of one clip. */
function videoRow({ userId, owner, video: v, c, base }) {
  const createdAt = v.at;
  return {
    _id: new (require('mongoose').Types.ObjectId)(), user: userId, status: 'completed', title: v.title, idea: v.idea, concept: v.idea, spokenLine: '', style: 'natural', language: 'english', voice: 'female',
    aspectRatio: '9:16', clips: 1, clipsDone: 1, parts: [], transition: 'fade', subtitles: false, logo: true, endLine: c.name, platforms: ['instagram', 'facebook'],
    notice: '', prompt: '', references: [], parent: null, change: '', videoUrl: `${base}/demo-assets/agency/${c.slug}/${mp4Rel(v)}`, seconds: demoVideos.SECONDS, quarks: QUARK_COSTS.studio_video, refunded: false,
    payer: owner, error: '', clipUrls: [], startedAt: createdAt, completedAt: new Date(createdAt.getTime() + 4 * 60000), createdAt, updatedAt: new Date(createdAt.getTime() + 4 * 60000)
  };
}

module.exports = { videoPlan, makeVideo, videoRow, mp4Rel, posterRel };
